<script setup lang="ts">
import { computed,onMounted,reactive,ref,watch } from 'vue';import { useRoute,useRouter } from 'vue-router';import { api } from '../api';
const route=useRoute();const router=useRouter();const section=computed(()=>String(route.params.section||'dashboard'));const data=ref<any>(null);const me=ref<any>(null);const error=ref('');const busy=ref(false);const selectedTenant=ref<any>(null);
const planForm=reactive<any>({code:'',name:{de:'',en:'',ru:''},description:{de:'',en:'',ru:''},price_monthly:19,price_yearly:190,currency:'EUR',trial_days:0,is_active:true,is_public:true,sort_order:50,badge_text:{},entitlements:{storage_mb:'2048',custom_domain:'0',staff_users:'1'}});const editingPlanId=ref<number|null>(null);const overrideForm=reactive({key:'',value:''});
const phraseForm=reactive<any>({category_id:null,variation_id:null,locale:'ru',phrase:'',weight:1,enabled:true});
const categoryForm=reactive<any>({code:'',name:{ru:'',de:'',en:''},enabled:true,sort_order:50});const variationForm=reactive<any>({category_id:null,code:'',name:{ru:'',de:'',en:''},template_code:'',enabled:true,priority:50});const templateForm=reactive<any>({category_id:null,variation_id:null,code:'',parent_code:'',name:{ru:'',de:'',en:''},configuration:'{"media":{"photos_min":1,"photos_max":5,"video_allowed":true},"fields":[]}',enabled:true,version:1,sort_order:50});
const tenantForm=reactive<any>({name:'',slug:'',owner_name:'',owner_email:'',owner_password:'',country:'DE',locale:'ru',business_description:'',variation_id:null,plan_id:null,complimentary:true});const lookups=ref<any>({plans:[],variations:[]});
const nav=[['dashboard','▦','Übersicht'],['tenants','◎','Kunden'],['users','♙','Benutzer'],['subscriptions','◉','Abonnements'],['plans','€','Tarife'],['stripe','S','Stripe'],['domains','◇','Domains'],['templates','≡','Vorlagen'],['ai','✦','KI-Wörterbuch'],['classifications','↯','KI-Entscheidungen'],['content','□','Inhalte & Einstellungen'],['backups','↥','Backups'],['audit','⌁','Prüfprotokoll']];
const metricLabels:any={tenants:'Kunden','active_tenants':'Aktive Kunden',trialing:'Testphase',paid:'Bezahlt',complimentary:'Kostenlos','domains_attention':'Domains prüfen','classifications_30d':'Klassifizierungen (30 Tage)','ai_spend_month':'KI-Kosten im Monat',mrr:'Monatlicher Umsatz'};
function adminLabel(key:string|number){const value=String(key);return metricLabels[value]||value.replaceAll('_',' ')}
async function load(){error.value='';try{me.value=await api('/me');if(!me.value.user?.is_super_admin)return router.push('/login');const endpoint:{[k:string]:string}={dashboard:'/control/dashboard',tenants:'/control/tenants',users:'/control/users',subscriptions:'/control/subscriptions',plans:'/control/plans',stripe:'/control/stripe',domains:'/control/domains',templates:'/control/taxonomy',ai:'/control/phrases',classifications:'/control/classifications',content:'/control/settings',backups:'/control/backups',audit:'/control/audits'};data.value=await api(endpoint[section.value]||endpoint.dashboard);if(['tenants','ai'].includes(section.value)){const [plans,taxonomy]=await Promise.all([api('/control/plans'),api('/control/taxonomy')]);lookups.value={plans,variations:taxonomy.categories.flatMap((c:any)=>c.variations)}}}catch(e:any){error.value=e.message;if(String(e.message).includes('Unauthenticated'))router.push('/login')}}
onMounted(load);watch(section,()=>{selectedTenant.value=null;load()});
async function openTenant(item:any){selectedTenant.value=await api(`/control/tenants/${item.id}`)}
async function updateTenant(payload:any){busy.value=true;try{await api(`/control/tenants/${selectedTenant.value.id}`,{method:'PUT',body:JSON.stringify(payload)});selectedTenant.value=await api(`/control/tenants/${selectedTenant.value.id}`);await load()}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function impersonate(){await api(`/control/tenants/${selectedTenant.value.id}/impersonate`,{method:'POST'});location.href='/app'}
async function toggleUser(user:any){await api(`/control/users/${user.id}`,{method:'PUT',body:JSON.stringify({is_active:!user.is_active})});await load()}
async function toggleAdmin(user:any){await api(`/control/users/${user.id}`,{method:'PUT',body:JSON.stringify({is_super_admin:!user.is_super_admin})});await load()}
async function resetPassword(user:any){await api(`/control/users/${user.id}/password-reset`,{method:'POST'});notice('Password reset requested')}
async function createTenant(){busy.value=true;try{await api('/control/tenants',{method:'POST',body:JSON.stringify(tenantForm)});Object.assign(tenantForm,{name:'',slug:'',owner_name:'',owner_email:'',owner_password:'',country:'DE',locale:'ru',business_description:'',variation_id:null,plan_id:null,complimentary:true});await load()}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function createPlan(){busy.value=true;try{await api(editingPlanId.value?`/control/plans/${editingPlanId.value}`:'/control/plans',{method:editingPlanId.value?'PUT':'POST',body:JSON.stringify(planForm)});editingPlanId.value=null;Object.assign(planForm,{code:'',name:{de:'',en:'',ru:''},description:{de:'',en:'',ru:''},price_monthly:19,price_yearly:190,currency:'EUR',trial_days:0,is_active:true,is_public:true,sort_order:50,badge_text:{},entitlements:{storage_mb:'2048',custom_domain:'0',staff_users:'1'}});await load()}catch(e:any){error.value=e.message}finally{busy.value=false}}
function editPlan(plan:any){editingPlanId.value=plan.id;Object.assign(planForm,{...plan,name:{...plan.name},description:{...(plan.description||{})},badge_text:{...(plan.badge_text||{})},entitlements:Object.fromEntries(plan.entitlements.map((e:any)=>[e.key,e.value]))});scrollTo({top:document.body.scrollHeight,behavior:'smooth'})}
async function setPlanState(plan:any,changes:any){const payload={...plan,...changes,entitlements:Object.fromEntries(plan.entitlements.map((e:any)=>[e.key,e.value]))};delete payload.subscriptions_count;await api(`/control/plans/${plan.id}`,{method:'PUT',body:JSON.stringify(payload)});await load()}
async function syncPlan(plan:any){busy.value=true;try{await api(`/control/plans/${plan.id}/stripe-sync`,{method:'POST'});await load()}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function syncAllPlans(){busy.value=true;try{await api('/control/stripe/sync-plans',{method:'POST'});await load()}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function backupAction(action:string,name?:string){busy.value=true;try{if(action==='delete'&&!confirm(`Delete backup ${name}?`))return;await api(name?`/control/backups/${name}/${action==='verify'?'verify':''}`.replace(/\/$/,''):'/control/backups',{method:action==='delete'?'DELETE':'POST'});await load()}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function domainAction(domain:any,action:string){busy.value=true;try{await api(`/control/domains/${domain.id}/${action}`,{method:'POST'});await load()}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function deleteDomain(domain:any){if(!confirm(`Delete ${domain.domain}?`))return;await api(`/control/domains/${domain.id}`,{method:'DELETE'});await load()}
async function toggleTemplate(template:any){await api(`/control/templates/${template.id}/toggle`,{method:'PUT',body:JSON.stringify({enabled:!template.enabled})});await load()}
async function toggleCategory(category:any){await api(`/control/categories/${category.id}`,{method:'PUT',body:JSON.stringify({...category,enabled:!category.enabled})});await load()}
async function toggleVariation(variation:any){await api(`/control/variations/${variation.id}`,{method:'PUT',body:JSON.stringify({...variation,enabled:!variation.enabled})});await load()}
async function addCategory(){await api('/control/categories',{method:'POST',body:JSON.stringify(categoryForm)});categoryForm.code='';categoryForm.name={ru:'',de:'',en:''};await load()}
async function addVariation(){await api('/control/variations',{method:'POST',body:JSON.stringify(variationForm)});variationForm.code='';variationForm.name={ru:'',de:'',en:''};variationForm.template_code='';await load()}
async function addTemplate(){try{await api('/control/templates',{method:'POST',body:JSON.stringify({...templateForm,configuration:JSON.parse(templateForm.configuration)})});templateForm.code='';templateForm.parent_code='';templateForm.name={ru:'',de:'',en:''};await load()}catch(e:any){error.value=e.message}}
function choosePhraseVariation(){const variation=lookups.value.variations.find((item:any)=>item.id===phraseForm.variation_id);phraseForm.category_id=variation?.category_id||null}
async function addPhrase(){busy.value=true;try{await api('/control/phrases',{method:'POST',body:JSON.stringify(phraseForm)});phraseForm.phrase='';await load()}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function togglePhrase(phrase:any){await api(`/control/phrases/${phrase.id}`,{method:'PUT',body:JSON.stringify({...phrase,enabled:!phrase.enabled})});await load()}
async function saveOverride(){await api(`/control/tenants/${selectedTenant.value.id}/entitlement`,{method:'PUT',body:JSON.stringify(overrideForm)});overrideForm.key='';overrideForm.value=''}
function notice(message:string){error.value='';window.alert(message)}
async function saveSetting(key:string,value:any){await api('/control/settings',{method:'PUT',body:JSON.stringify({key,value})});await load()}
async function savePage(page:any){await api(`/control/pages/${page.id}`,{method:'PUT',body:JSON.stringify({title:page.title,content:page.content,is_published:page.is_published})});await load()}
async function logout(){await api('/logout',{method:'POST'});router.push('/login')}
</script>
<template><div class="control-shell"><aside class="control-sidebar"><div class="control-wordmark"><b>LOOK</b><span>DO</span><small>SUPER ADMIN</small></div><nav><RouterLink v-for="item in nav" :key="item[0]" :to="`/control/${item[0]}`" :class="{active:section===item[0]}"><span>{{item[1]}}</span>{{item[2]}}</RouterLink></nav><button class="sidebar-logout" @click="logout">Abmelden</button></aside><main class="control-main"><header class="control-header"><div><p class="eyebrow">LOOKDO VERWALTUNG</p><h1>{{nav.find(x=>x[0]===section)?.[2]}}</h1></div><div class="admin-chip"><span>SA</span><div><b>{{me?.user?.name}}</b><small>{{me?.user?.email}}</small></div></div></header><p v-if="error" class="alert error">{{error}}</p><div v-if="!data" class="loading">Wird geladen…</div>
<template v-else><section v-if="section==='dashboard'" class="admin-metrics"><article v-for="(value,key) in data" :key="key"><span>{{adminLabel(key)}}</span><strong>{{key==='mrr'?`${Number(value).toFixed(2)} €`:value}}</strong></article></section>
<section v-if="section==='tenants'" class="admin-section"><form class="admin-card form-grid" @submit.prevent="createTenant"><h2 class="wide">Kunden anlegen</h2><label>Unternehmen<input v-model="tenantForm.name" required></label><label>Subdomain<input v-model="tenantForm.slug" placeholder="automatisch"></label><label>Name des Inhabers<input v-model="tenantForm.owner_name" required></label><label>E-Mail des Inhabers<input v-model="tenantForm.owner_email" type="email" required></label><label>Temporäres Passwort<input v-model="tenantForm.owner_password" type="password" minlength="10" required></label><label>Tarif<select v-model.number="tenantForm.plan_id" required><option :value="null">Bitte wählen</option><option v-for="plan in lookups.plans" :key="plan.id" :value="plan.id">{{plan.name.de||plan.code}}</option></select></label><label>Geschäftsvorlage<select v-model.number="tenantForm.variation_id"><option :value="null">Nicht ausgewählt</option><option v-for="variation in lookups.variations" :key="variation.id" :value="variation.id">{{variation.name.de||variation.code}}</option></select></label><label class="check"><input v-model="tenantForm.complimentary" type="checkbox"> Kostenlos</label><label class="wide">Tätigkeitsbeschreibung<textarea v-model="tenantForm.business_description"></textarea></label><button class="button" :disabled="busy">Kunden anlegen</button></form><div class="admin-table-wrap"><table><thead><tr><th>Kunde</th><th>Inhaber</th><th>Vorlage</th><th>Domain</th><th>Tarif</th><th>Status</th></tr></thead><tbody><tr v-for="tenant in data.data" :key="tenant.id" @click="openTenant(tenant)"><td><b>{{tenant.name}}</b><small>{{tenant.slug}}</small></td><td>{{tenant.users?.[0]?.email}}</td><td>{{tenant.business_profile?.variation?.code||'—'}}</td><td>{{tenant.primary_domain?.domain}}</td><td>{{tenant.current_subscription?.plan?.code||'—'}}</td><td><span class="table-status">{{tenant.status}}</span></td></tr></tbody></table></div><aside v-if="selectedTenant" class="drawer"><button class="drawer-close" @click="selectedTenant=null">×</button><p class="eyebrow">KUNDE #{{selectedTenant.id}}</p><h2>{{selectedTenant.name}}</h2><p>{{selectedTenant.slug}}.lookdo.app</p><dl><div><dt>Inhaber</dt><dd>{{selectedTenant.users?.[0]?.email}}</dd></div><div><dt>Tarif</dt><dd>{{selectedTenant.current_subscription?.plan?.code||'—'}}</dd></div><div><dt>Status</dt><dd>{{selectedTenant.status}}</dd></div></dl><button class="button full" @click="impersonate">Kundenkonto öffnen</button><div class="drawer-actions"><button class="button ghost" @click="updateTenant({status:selectedTenant.status==='active'?'suspended':'active'})">{{selectedTenant.status==='active'?'Sperren':'Aktivieren'}}</button><button class="button ghost" @click="updateTenant({plan_id:selectedTenant.current_subscription?.plan_id,complimentary:true,discount_percent:100})">Kostenlos</button></div><h3>Tarif ändern</h3><select v-model.number="selectedTenant.current_subscription.plan_id"><option v-for="plan in lookups.plans" :key="plan.id" :value="plan.id">{{plan.name.de||plan.code}}</option></select><button class="button ghost small" @click="updateTenant({plan_id:selectedTenant.current_subscription.plan_id,complimentary:selectedTenant.current_subscription.complimentary,discount_percent:selectedTenant.current_subscription.discount_percent})">Tarif speichern</button><h3>Leistung überschreiben</h3><input v-model="overrideForm.key" placeholder="Schlüssel"><input v-model="overrideForm.value" placeholder="Wert"><button class="button ghost small" @click="saveOverride">Speichern</button><h3>Domains</h3><p v-for="domain in selectedTenant.domains" :key="domain.id">{{domain.domain}} · {{domain.status}}</p></aside></section>
<section v-if="section==='users'" class="admin-section"><div class="admin-table-wrap"><table><thead><tr><th>Benutzer</th><th>Kunde</th><th>Rolle</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="user in data.data" :key="user.id"><td><b>{{user.name}}</b><small>{{user.email}}</small></td><td>{{user.tenants?.map((t:any)=>t.name).join(', ')||'Plattform'}}</td><td>{{user.is_super_admin?'Super Admin':user.tenants?.[0]?.pivot?.role}}</td><td>{{user.is_active?'aktiv':'gesperrt'}}</td><td><button class="link-button" @click="toggleUser(user)">{{user.is_active?'Sperren':'Aktivieren'}}</button><button class="link-button" @click="resetPassword(user)">Zugang zurücksetzen</button><button class="link-button" @click="toggleAdmin(user)">{{user.is_super_admin?'Admin entziehen':'Zum Admin machen'}}</button></td></tr></tbody></table></div></section>
<section v-if="section==='subscriptions'" class="admin-section"><div class="admin-table-wrap"><table><thead><tr><th>Kunde</th><th>Tarif</th><th>Anbieter</th><th>Status</th><th>Periodenende</th><th>Rabatt</th><th>IDs</th></tr></thead><tbody><tr v-for="subscription in data.data" :key="subscription.id"><td><b>{{subscription.tenant?.name}}</b><small>{{subscription.tenant?.slug}}</small></td><td>{{subscription.plan?.code}}</td><td>{{subscription.provider}}</td><td>{{subscription.status}}<small v-if="subscription.complimentary">kostenlos</small></td><td>{{subscription.current_period_end||'—'}}<small v-if="subscription.cancel_at_period_end">wird gekündigt</small></td><td>{{subscription.discount_percent}}%</td><td><small>{{subscription.provider_customer_id||'—'}}</small><small>{{subscription.provider_subscription_id||'—'}}</small></td></tr></tbody></table></div></section>
<section v-if="section==='plans'" class="admin-section"><div class="plan-admin-grid"><article v-for="plan in data" :key="plan.id" class="admin-card"><div class="row-between"><div><p class="eyebrow">{{plan.code}}</p><h2>{{plan.name.de||plan.name.ru}}</h2></div><span class="table-status">{{plan.is_active?(plan.is_public?'öffentlich':'ausgeblendet'):'archiviert'}}</span></div><strong class="admin-price">{{plan.price_monthly}} €</strong><p>{{plan.description.de||plan.description.ru}}</p><div class="tag-list"><span v-for="e in plan.entitlements" :key="e.id">{{e.key}}={{e.value}}</span></div><button class="button ghost small" @click="editPlan(plan)">Bearbeiten</button><button class="button ghost small" @click="setPlanState(plan,{is_public:!plan.is_public})">{{plan.is_public?'Ausblenden':'Veröffentlichen'}}</button><button class="button ghost small" @click="setPlanState(plan,{is_active:!plan.is_active})">{{plan.is_active?'Archivieren':'Aktivieren'}}</button><button class="button ghost small" :disabled="busy" @click="syncPlan(plan)">Mit Stripe synchronisieren</button><small v-if="plan.stripe_sync_error">{{plan.stripe_sync_error}}</small></article></div><form class="admin-card form-grid" @submit.prevent="createPlan"><h2 class="wide">{{editingPlanId?'Tarif bearbeiten':'Neuer Tarif'}}</h2><label>Code<input v-model="planForm.code" required></label><label>Monatspreis<input v-model.number="planForm.price_monthly" type="number" required></label><label>Jahrespreis<input v-model.number="planForm.price_yearly" type="number"></label><label>Währung<input v-model="planForm.currency" maxlength="3" required></label><label>Deutscher Name<input v-model="planForm.name.de" required></label><label>Englischer Name<input v-model="planForm.name.en" required></label><label class="wide">Russischer Name<input v-model="planForm.name.ru" required></label><label>Testtage<input v-model.number="planForm.trial_days" type="number"></label><label>Sortierung<input v-model.number="planForm.sort_order" type="number"></label><label class="check"><input v-model="planForm.is_active" type="checkbox"> Aktiv</label><label class="check"><input v-model="planForm.is_public" type="checkbox"> Öffentlich</label><label class="wide">Deutsche Beschreibung<textarea v-model="planForm.description.de"></textarea></label><label class="wide">Englische Beschreibung<textarea v-model="planForm.description.en"></textarea></label><label class="wide">Russische Beschreibung<textarea v-model="planForm.description.ru"></textarea></label><button class="button">{{editingPlanId?'Tarif speichern':'Tarif erstellen'}}</button></form></section>
<section v-if="section==='stripe'" class="admin-section"><article class="admin-card"><p class="eyebrow">ZAHLUNGEN</p><h2>{{data.configured?'Stripe verbunden':'Stripe ist nicht konfiguriert'}}</h2><p v-if="data.account">Konto {{data.account.id}} · {{data.account.livemode?'Live-Modus':'Testmodus'}} · {{data.account.country}}</p><p>Webhook: {{data.webhook_configured?'konfiguriert':'nicht konfiguriert'}} · Ausstehende Tarife: {{data.plans_pending}}</p><button class="button" :disabled="busy||!data.configured" @click="syncAllPlans">Alle Tarife synchronisieren</button><p><small>Das Webhook-Signaturgeheimnis wird vom Installationsbefehl erstellt und hier nie angezeigt.</small></p></article></section>
<section v-if="section==='domains'" class="admin-section"><div class="admin-table-wrap"><table><thead><tr><th>Domain</th><th>Kunde</th><th>Typ</th><th>DNS / SSL</th><th>Geprüft</th><th></th></tr></thead><tbody><tr v-for="domain in data.data" :key="domain.id"><td><b>{{domain.domain}}</b></td><td>{{domain.tenant?.name}}</td><td>{{domain.type}}</td><td>{{domain.status}} / {{domain.ssl_status||'—'}}</td><td>{{domain.last_checked_at||'—'}}</td><td><button v-if="domain.type==='custom'" class="link-button" @click="domainAction(domain,'verify')">Prüfen</button><button v-if="domain.status==='ssl_pending'" class="link-button" @click="domainAction(domain,'activate')">Aktivieren</button><button v-if="domain.type==='custom'&&domain.status==='active'" class="link-button" @click="domainAction(domain,'disable')">Deaktivieren</button><button v-if="domain.type==='custom'&&domain.status!=='active'" class="link-button" @click="deleteDomain(domain)">Löschen</button></td></tr></tbody></table></div></section>
<section v-if="section==='templates'" class="admin-section"><div class="taxonomy-grid"><article class="admin-card" v-for="category in data.categories" :key="category.id"><div class="row-between"><h2>{{category.name.de||category.name.ru}}</h2><button class="link-button" @click="toggleCategory(category)">{{category.enabled?'Deaktivieren':'Aktivieren'}}</button></div><div class="variation" v-for="variation in category.variations" :key="variation.id"><b>{{variation.name.de||variation.name.ru}}</b><code>{{variation.code}}</code><span>Priorität {{variation.priority}}</span><button class="link-button" @click="toggleVariation(variation)">{{variation.enabled?'Deaktivieren':'Aktivieren'}}</button></div></article></div><div class="settings-grid"><form class="admin-card form-grid" @submit.prevent="addCategory"><h2 class="wide">Neue Kategorie</h2><label>Code<input v-model="categoryForm.code" required></label><label>Sortierung<input v-model.number="categoryForm.sort_order" type="number"></label><label>Russisch<input v-model="categoryForm.name.ru" required></label><label>Deutsch<input v-model="categoryForm.name.de"></label><label>Englisch<input v-model="categoryForm.name.en"></label><button class="button">Kategorie erstellen</button></form><form class="admin-card form-grid" @submit.prevent="addVariation"><h2 class="wide">Neue Variante</h2><label>Kategorie<select v-model.number="variationForm.category_id" required><option v-for="category in data.categories" :key="category.id" :value="category.id">{{category.name.de||category.code}}</option></select></label><label>Code<input v-model="variationForm.code" required></label><label>Russisch<input v-model="variationForm.name.ru" required></label><label>Deutsch<input v-model="variationForm.name.de"></label><label>Englisch<input v-model="variationForm.name.en"></label><label>Vorlagen-Code<input v-model="variationForm.template_code"></label><label>Priorität<input v-model.number="variationForm.priority" type="number"></label><button class="button">Variante erstellen</button></form></div><div class="admin-table-wrap"><table><thead><tr><th>Vorlage</th><th>Übergeordnet</th><th>Version</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="template in data.templates" :key="template.id"><td><b>{{template.code}}</b></td><td>{{template.parent_code||'—'}}</td><td>{{template.version}}</td><td>{{template.enabled?'aktiv':'deaktiviert'}}</td><td><button class="link-button" @click="toggleTemplate(template)">{{template.enabled?'Deaktivieren':'Aktivieren'}}</button></td></tr></tbody></table></div><form class="admin-card form-grid" @submit.prevent="addTemplate"><h2 class="wide">Neue Anfragevorlage</h2><label>Kategorie<select v-model.number="templateForm.category_id"><option :value="null">Keine</option><option v-for="category in data.categories" :key="category.id" :value="category.id">{{category.name.de||category.code}}</option></select></label><label>Varianten-ID<input v-model.number="templateForm.variation_id" type="number"></label><label>Code<input v-model="templateForm.code" required></label><label>Übergeordneter Code<input v-model="templateForm.parent_code"></label><label>Russischer Name<input v-model="templateForm.name.ru" required></label><label>Version<input v-model.number="templateForm.version" type="number"></label><label class="wide">Konfiguration (JSON)<textarea v-model="templateForm.configuration" rows="8" required></textarea></label><button class="button">Vorlage erstellen</button></form></section>
<section v-if="section==='ai'" class="admin-section"><form class="admin-card phrase-form" @submit.prevent="addPhrase"><div><p class="eyebrow">WÖRTERBUCH</p><h2>Geschäftsbegriff hinzufügen</h2></div><label>Sprache<select v-model="phraseForm.locale"><option value="de">Deutsch</option><option value="en">Englisch</option><option value="ru">Russisch</option><option value="uk">Ukrainisch</option></select></label><label>Vorlage<select v-model.number="phraseForm.variation_id" required @change="choosePhraseVariation"><option :value="null">Bitte wählen</option><option v-for="variation in lookups.variations" :key="variation.id" :value="variation.id">{{variation.name.de||variation.name.ru||variation.code}}</option></select></label><label>Begriff<input v-model="phraseForm.phrase" required></label><button class="button">Hinzufügen</button></form><div class="admin-table-wrap"><table><thead><tr><th>Begriff</th><th>Sprache</th><th>Kategorie</th><th>Vorlage</th><th>Gewichtung</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="phrase in data.data" :key="phrase.id"><td><b>{{phrase.phrase}}</b><small>{{phrase.normalized_phrase}}</small></td><td>{{phrase.locale}}</td><td>{{phrase.category?.name?.de||phrase.category?.code}}</td><td>{{phrase.variation?.name?.de||phrase.variation?.code}}</td><td>{{phrase.weight}}</td><td>{{phrase.enabled?'aktiv':'aus'}}</td><td><button class="link-button" @click="togglePhrase(phrase)">{{phrase.enabled?'Deaktivieren':'Aktivieren'}}</button></td></tr></tbody></table></div></section>
<section v-if="section==='classifications'" class="admin-section"><div class="admin-table-wrap"><table><thead><tr><th>Datum</th><th>Eingabe</th><th>Kunde</th><th>Ergebnis</th><th>Sicherheit</th><th>Quelle</th><th>Bestätigt</th></tr></thead><tbody><tr v-for="item in data.data" :key="item.id"><td>{{item.created_at}}</td><td><b>{{item.original_text}}</b><small>{{item.normalized_text}}</small></td><td>{{item.tenant?.name||'Registrierung'}}</td><td>{{item.category?.code||'—'}}<small>{{item.variation?.code||'allgemein'}}</small></td><td>{{Math.round(Number(item.confidence)*100)}}%</td><td>{{item.source}}{{item.ai_model?` · ${item.ai_model}`:''}}</td><td>{{item.confirmed_by_user_at?'ja':'nein'}}</td></tr></tbody></table></div></section>
<section v-if="section==='content'" class="admin-section"><div class="settings-grid"><article class="admin-card"><h2>Systemeinstellungen</h2><label v-for="(value,key) in data.settings" :key="key">{{String(key).replaceAll('_',' ')}}<div class="setting-row"><input :value="typeof value==='object'?JSON.stringify(value):String(value)" @change="saveSetting(String(key),($event.target as HTMLInputElement).value)"><span>Beim Ändern speichern</span></div></label></article><article v-for="page in data.pages" :key="page.id" class="admin-card page-editor"><div class="row-between"><div><p class="eyebrow">/{{page.key}}</p><h2>{{page.title.de}}</h2></div><label class="check"><input v-model="page.is_published" type="checkbox"> Veröffentlicht</label></div><label>Deutscher Titel<input v-model="page.title.de"></label><label>Deutscher Inhalt<textarea v-model="page.content.de" rows="6"></textarea></label><label>Englischer Inhalt<textarea v-model="page.content.en" rows="4"></textarea></label><label>Russischer Inhalt<textarea v-model="page.content.ru" rows="4"></textarea></label><label>Ukrainischer Inhalt<textarea v-model="page.content.uk" rows="4"></textarea></label><button class="button small" @click="savePage(page)">Seite speichern</button></article></div></section>
<section v-if="section==='backups'" class="admin-section"><article class="admin-card"><p class="eyebrow">DATENSICHERUNG</p><h2>Server-Backups</h2><p>{{data.path}} · Aufbewahrung {{data.keep}}</p><button class="button" :disabled="busy" @click="backupAction('create')">Backup jetzt erstellen</button></article><div class="admin-table-wrap"><table><thead><tr><th>Backup</th><th>Erstellt</th><th>Dateien</th><th></th></tr></thead><tbody><tr v-for="backup in data.backups" :key="backup.name"><td><b>{{backup.name}}</b></td><td>{{backup.created_at}}</td><td>{{Object.keys(backup.files).length}}</td><td><button class="link-button" @click="backupAction('verify',backup.name)">Prüfen</button><button class="link-button" @click="backupAction('delete',backup.name)">Löschen</button></td></tr></tbody></table></div></section>
<section v-if="section==='audit'" class="admin-section"><div class="admin-table-wrap"><table><thead><tr><th>Datum</th><th>Aktion</th><th>Benutzer</th><th>Kunde</th><th>Objekt</th></tr></thead><tbody><tr v-for="log in data.data" :key="log.id"><td>{{log.created_at}}</td><td><b>{{log.action}}</b></td><td>{{log.actor_id||'System'}}</td><td>{{log.tenant_id||'—'}}</td><td>{{log.subject_type}} #{{log.subject_id}}</td></tr></tbody></table></div></section>
</template></main></div></template>
